-- Datos de demostración. Conserva existencias y ediciones de cada SKU.
ON CONFLICT (sku_demo) DO UPDATE SET
    nombre = EXCLUDED.nombre,
    descripcion = EXCLUDED.descripcion,
    categoria = EXCLUDED.categoria,
    descripcion_larga = EXCLUDED.descripcion_larga,
    incluye = EXCLUDED.incluye,
    compatibilidad = EXCLUDED.compatibilidad,
    nota_estado = EXCLUDED.nota_estado,
    especificaciones = EXCLUDED.especificaciones
WHERE strpos(products.descripcion, chr(194)) > 0 OR strpos(products.descripcion, chr(195)) > 0;
